(() => {
  const summary=document.querySelector('.order-summary');
  if(!summary)return;
  let choice;try{choice=JSON.parse(sessionStorage.getItem('jtm-flight-choice')||'')}catch{}
  if(!choice?.flight)return;
  const clean=value=>String(value||'').replace(/\b(Bandar Udara|Airport|Internasional|International)\b/gi,'').replace(/\s+/g,' ').trim();
  const code=(airport,fallback)=>String(airport?.id||airport?.iata||fallback||'').toUpperCase();
  const time=value=>{const date=new Date(String(value||'').replace(' ','T'));return Number.isNaN(date.valueOf())?'—':new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(date)};
  const sector=(title,flight,from,to)=>{const legs=flight?.flights||[],first=legs[0]||{},last=legs.at(-1)||first;return `<section class="checkout-sector"><h3>${title}</h3><b>${clean(first.departure_airport?.name)||from} (${code(first.departure_airport,from)}) → ${clean(last.arrival_airport?.name)||to} (${code(last.arrival_airport,to)})</b>${legs.map(leg=>`<div class="checkout-leg"><strong>${clean(leg.departure_airport?.name)} (${code(leg.departure_airport,from)}) → ${clean(leg.arrival_airport?.name)} (${code(leg.arrival_airport,to)})</strong><span>${leg.airline||''} ${leg.flight_number||''} · ${time(leg.departure_airport?.time)} – ${time(leg.arrival_airport?.time)}</span></div>`).join('')}</section>`};
  const currency=choice.search?.currency||'IDR',price=new Intl.NumberFormat('id-ID',{style:'currency',currency,maximumFractionDigits:0}).format(Number(choice.flight.price||0)),isReturn=Boolean(choice.returnFlight);
  const from=choice.search?.origin||'',to=choice.search?.destination||'';
  summary.innerHTML=`<h2>Ringkasan penerbangan</h2><p class="checkout-summary-route">${from} → ${to}${isReturn?` · pulang ${to} → ${from}`:''}</p><p class="checkout-summary-intro">Periksa jadwal sebelum mengirim permintaan.</p><button class="checkout-schedule-toggle" type="button" aria-expanded="false">Lihat jadwal lengkap</button><div class="checkout-itineraries" hidden>${sector('Pergi',choice.flight,from,to)}${isReturn?sector('Pulang',choice.returnFlight,to,from):''}</div><hr><div class="order-total"><span>Harga indikatif ${isReturn?'pergi–pulang':'per orang'}</span><b>${price}</b></div><small>Harga ditampilkan dalam ${currency} dan sudah termasuk estimasi pajak. Harga serta ketersediaan dikonfirmasi sebelum tiket diterbitkan.</small>`;
  const toggle=summary.querySelector('.checkout-schedule-toggle'),itineraries=summary.querySelector('.checkout-itineraries');
  toggle.addEventListener('click',()=>{itineraries.hidden=!itineraries.hidden;toggle.setAttribute('aria-expanded',String(!itineraries.hidden));toggle.textContent=itineraries.hidden?'Lihat jadwal lengkap':'Sembunyikan jadwal lengkap';});
  document.head.insertAdjacentHTML('beforeend','<style>.checkout-summary-route{margin:0;color:#172033;font-weight:700;line-height:1.45}.checkout-summary-intro{margin:6px 0 16px;color:#526b8e;font-size:.84rem}.checkout-schedule-toggle{width:100%;border:1px solid #1e3a8a;border-radius:7px;background:#fff;color:#1e3a8a;padding:10px 12px;font:700 .84rem DM Sans;cursor:pointer}.checkout-schedule-toggle:hover{background:#eff6ff}.checkout-itineraries{display:grid;gap:13px;margin-top:14px}.checkout-sector{padding:14px;border:1px solid #dbe3ec;border-radius:9px;background:#f8fbff}.checkout-sector h3{margin:0 0 8px;color:#1e3a8a;font-size:.88rem}.checkout-sector>b{display:block;line-height:1.45}.checkout-leg{padding:10px 0 0;margin-top:10px;border-top:1px solid #dbe3ec}.checkout-leg strong,.checkout-leg span{display:block;font-size:.8rem;line-height:1.45}.checkout-leg span{color:#526b8e}</style>');
})();
